 const employee=state.employees.find(e=>e.id===actor)||state.employees[0];const isAdmin=employee.role==="admin";const canView=(v:View)=>v==="settings"?isAdmin:isAdmin?!["mine","rework"].includes(v):v==="rework"?employee.role==="operator":["moscow","post"].includes(v)?employee.role==="logistic":v==="rules"?false:employee.role==="redemption"?v==="redemption":employee.role==="department_head"&&["check","shipping"].includes(v)?false:v==="redemption"?["redemption","department_head"].includes(employee.role):v==="incoming"?["operator","admin","department_head"].includes(employee.role):v==="warehouse"?["admin","logistic"].includes(employee.role):employee.role==="logistic"&&["mine","check"].includes(v)?false:v==="base"?isAdmin:v==="mine"?!isAdmin:employee.role!=="operator"||!["confirm","check","shipping","team"].includes(v);const view:View=canView(requestedView)?requestedView:isAdmin?"base":employee.role==="redemption"?"redemption":employee.role==="logistic"?"confirm":"mine";const selectedClient=detail?.type==="client"?state.clients.find(c=>c.id===detail.id):undefined;const selectedOrder=detail?.type==="order"?state.orders.find(o=>o.id===detail.id):undefined;
 const shippingView=["shipping","moscow","post"].includes(view);
 useEffect(()=>{if(view==="orders"||view==="rework"||view==="confirm"||shippingView)setFilter("new");},[view,actor]);
