 useEffect(()=>{for(const o of dueCalls){const key=`${actor}:${o.id}:${o.due}`;if(notifiedCalls.current.has(key))continue;notifiedCalls.current.add(key);toast.warning("Пора позвонить клиенту",{description:`${state.clients.find(c=>c.id===o.clientId)?.name||o.id} · ${stamp(o.due)}`,duration:10000,closeButton:true,action:{label:"Открыть заказ",onClick:()=>setDetail({type:"order",id:o.id})}});}},[state,actor,reminderNow,ready]);
 async function load(){setLoadError("");try{const r=await fetch("/api/crm",{cache:"no-store"});const d:any=await r.json();if(r.status===401){window.location.replace("/login");return;}if(!r.ok)throw Error(d.error);setPersonalAuth(d.personalAuth===true);if(d.currentEmployeeId)setActor(d.currentEmployeeId);setState(d);setReady(true);}catch(e){setLoadError(e instanceof Error?e.message:"Не удалось загрузить данные");}}
 useEffect(()=>{void load();const refresh=()=>{void load();};window.addEventListener("crm-refresh",refresh);return()=>window.removeEventListener("crm-refresh",refresh);},[]);
